python3 -I - <<'EOF'
head=open('/tmp/hf_head.txt').read()
scenes=[('mic',0,2.5),('board',2.5,2.3),('title',4.8,1.6),('scan',6.4,7),('logbook',13.4,5),('collect',18.4,2.8),('end',21.2,2.8)]
hosts='\n'.join(f'      <div id="{c}-host" data-composition-id="{c}" data-composition-src="compositions/{c}.html" data-start="{s}" data-duration="{d}" data-track-index="1" data-width="1920" data-height="1080"></div>' for c,s,d in scenes)
sfx_times=[2.15,4.4,6.05,13.05,18.05,20.8]
sfx='\n'.join(f'      <audio id="sfx-{i+1}" src="assets/Fast synthetic whoosh.mp3" data-start="{round(t-0.18,2)}" data-duration="1.5" data-volume="0.7" data-track-index="{6+i%2}"></audio>' for i,t in enumerate(sfx_times))
body=f'''<body>
    <div data-hf-id="hf-199x" id="root" data-composition-id="main" data-start="0" data-duration="24" data-width="1920" data-height="1080">
      <div id="sky"></div>
      <div id="stars"></div>

{hosts}

      <div id="vignette"></div>
      <div id="flash"></div>

      <audio id="music" src="assets/Astral Generated Music ed870be8.wav" data-start="0" data-duration="24" data-volume="0.55" data-track-index="5" data-automation='{{"volume":[{{"t":0,"v":0}},{{"t":0.4,"v":1}},{{"t":22.4,"v":1}},{{"t":24,"v":0}}]}}'></audio>
{sfx}
    </div>
    <script>
      // Deterministic star field
      (function () {{
        const field = document.getElementById("stars");
        let seed = 7;
        const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
        for (let i = 0; i < 90; i++) {{
          const s = document.createElement("div");
          s.className = "star";
          s.style.left = (rnd() * 2040).toFixed(1) + "px";
          s.style.top = (rnd() * 1200).toFixed(1) + "px";
          s.style.opacity = (0.25 + rnd() * 0.75).toFixed(2);
          const k = 0.5 + rnd() * 1.2;
          s.style.width = s.style.height = (2 * k).toFixed(1) + "px";
          field.appendChild(s);
        }}
      }})();

      const tl = gsap.timeline({{ paused: true }});

