        tl.to(".m-rule", { opacity: 0, duration: 0.4, ease: "power2.in" }, D + 0.2);

        // --- eight logbook birds swirl in clockwise and orbit the badge ---
        const O = D + 0.35;
        tl.fromTo(".m-tile", { opacity: 0 }, { opacity: 1, duration: 0.25, ease: "power1.out" }, O);
        tl.fromTo(".m-radial", { x: 640 }, { x: 340, duration: 0.8, ease: "expo.out" }, O);
        // the swirl: fast, then a slow orbit that never stops; a second spin speeds the exit
        tl.fromTo(".m-spin", { rotate: -120 }, { rotate: 60, duration: 2.0, ease: "expo.out" }, O);
        tl.fromTo(".m-up2", { rotate: 120 }, { rotate: -60, duration: 2.0, ease: "expo.out" }, O);
        tl.fromTo(".m-spin2", { rotate: 0 }, { rotate: 150, duration: 1.5, ease: "power2.in" }, O + 1.5);
        tl.fromTo(".m-up3", { rotate: 0 }, { rotate: -150, duration: 1.5, ease: "power2.in" }, O + 1.5);
        // the badge discs grow at the centre while the panel square fades behind them
        tl.fromTo("#m-disc-out", { opacity: 0, scale: 0.45 }, { opacity: 1, scale: 1, duration: 0.5, ease: "expo.out" }, O + 0.3);
        tl.fromTo("#m-disc-in", { opacity: 0, scale: 0.45 }, { opacity: 1, scale: 1, duration: 0.5, ease: "expo.out" }, O + 0.36);
        tl.to("#m-panel", { opacity: 0, duration: 0.5, ease: "power2.out" }, O + 0.4);
        // tiles leave clockwise, one after another, on an expanding orbit
        const X = O + 2.05;
        for (let i = 0; i < 8; i++) {
          const k = (i + 3) % 8;
          tl.to("#m-rad-" + k, { x: 1150, duration: 0.45, ease: "none" }, X + i * 0.05);
          tl.to("#m-tile-" + k, { opacity: 0, duration: 0.3, ease: "power1.in" }, X + 0.12 + i * 0.05);
        }
        // the badge glides out left as the mark sets off, blur peaking at the cut
        tl.to("#m-badge", { x: -230, duration: 0.33, ease: "power4.in" }, 10.17);
