log.command:
python3 -I - <<'EOF'
p='compositions/hook.html'; s=open(p).read()
s=s.replace('''        // Lines drift in softly, keep gliding left at a steady pace, then glitch away.
        // Lines drift in softly''','''        // Lines drift in softly''',1)
restore='''        // The rig arrives already moving left (cut-the-curve entry)
        tl.fromTo("#hook-strip", { x: 230, opacity: 0.35 }, { x: 0, opacity: 1, duration: 0.42, ease: "power4.out", immediateRender: true }, 0);
        // 1. The mic in hand scales up until it fills the screen
        tl.fromTo("#hook-mic", { scale: 1, borderRadius: 30 }, { scale: 4.6, borderRadius: 7, duration: 1.2, ease: "expo.inOut" }, 0.45);
        tl.to("#hook-mic", { scale: 5.3, duration: 0.9, ease: "power2.in" }, 1.65);
        tl.to("#hook-mic", { opacity: 0, duration: 0.5, ease: "power2.in" }, 2.05);
        // 2. The breadboard card lands over it, then scales up to fill the screen too
        tl.fromTo("#hook-board", { opacity: 0, x: 230, scale: 0.9 }, { opacity: 1, x: 0, scale: 1, duration: 0.5, ease: "power3.out" }, 2.0);
        tl.fromTo("#hook-board", { borderRadius: 30 }, { scale: 3.15, borderRadius: 10, duration: 0.95, ease: "expo.inOut", immediateRender: false }, 2.5);
        tl.to("#hook-board", { scale: 3.5, duration: 1.2, ease: "power1.in" }, 3.45);
'''
s=s.replace('        stackLife("#hook-carry"', restore+'        stackLife("#hook-carry"',1)
open(p,'w').write(s)
EOF
